 refs=[b.ref(b.UNIT/n) for n in ['verify_authority_profile.py','carrier-consumer-inspection.json','carrier-inspection-command-result.json','CONSUMER-REVIEW.md','types-logic-receipt.json']];retained=[];b.unchanged(refs+list(observation['selected_inputs'].values())+retained)
 report={'schema_version':'definition-assurance-Goal-authority-profile/v1-candidate','status':'PASS-for-qualified-Goal-hypotheses-and-six-current-carrier-comparisons','authority_effect':'none','source':context['source_selection'],'profiles':ps,'finite_comparison_frames':fs,'source_map_obligations':MAP_FIELDS,'accepted_source_to_carrier_or_consumer_map_refs':[],'cross_definition_review_findings':findings,'actual_checks':observation['checks'],'actual_check_count':observation['check_count'],'carrier_consumer_observation':observation,'selected_inputs':{str(i):x for i,x in enumerate(refs+list(observation['selected_inputs'].values())+retained)},'checker_bindings':[b.ref(b.UNIT/'verify_authority_profile.py'),b.ref(b.UNIT/'inspect_carrier_consumers.py'),b.ref(b.IMPL/'contracts.py')],'runtime_bindings':runtime,'bound_package_validator_executed':False,'canonical_or_candidate_carrier_writer_executed':False,'native_or_live_consumer_executed':False,'isolated_pure_Definition_and_identity_helpers_executed':True,'isolated_pure_semantic_helper_executed':True,'actual_Goal_achievement_permission_or_authority_created':False,'direct_carrier_or_consumer_alignment_accepted':False,'retained_failed_consumer_comparison_refs':retained,'new_authorities_or_relations_created':0,'source_fidelity':'pending','semantic_ready':False,'mechanized_proof':False,'claim_ceiling':'Qualified Goal maps and six exact C30/C31carriers only;actual membership,required-condition completeness,evidence adequacy,owner authorization,lifecycle,achievement,source fidelity and whole proof remain independent.'}
 assert runtime==v.f.current_bindings();b.unchanged(context['sources']);b.external_current(context)
 if write:b.put('authority-profile-checks.json',report)
